import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.CWSmAuPU.js";const p=JSON.parse('{"title":"0013 发布不使用 changesets 等工具","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0013-no-release-tooling.md","filePath":"reference/adr/0013-no-release-tooling.md","lastUpdated":null}'),s={name:"reference/adr/0013-no-release-tooling.md"};function n(i,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0013-发布不使用-changesets-等工具" tabindex="-1">0013 发布不使用 changesets 等工具 <a class="header-anchor" href="#_0013-发布不使用-changesets-等工具" aria-label="Permalink to &quot;0013 发布不使用 changesets 等工具&quot;">​</a></h1><ul><li>状态：已采纳（取代设计方案中&quot;由 changesets 维护 CHANGELOG&quot;的计划）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>设计方案计划用 changesets 维护版本号和 CHANGELOG。req-kit 是单一包、发布频率低，CHANGELOG 的主要读者是使用者和安装者，需要&quot;使用者会看到的变化&quot;和&quot;升级须知&quot;这样的结构，工具生成的条目还要人工改写。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><p>版本号和 CHANGELOG 由维护者按 <a href="./../../guide/maintainer">维护者指南</a> 的发布流程手工维护；标签不带 <code>v</code> 前缀。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>少一个开发依赖。需要维护者在每次发布时认真写 CHANGELOG；发布流程中的验证步骤由指南约束。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0013-no-release-tooling.md">docs/adr/0013-no-release-tooling.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0013-no-release-tooling.md">在 GitHub 上编辑</a></p>',2)])])}const _=a(s,[["render",n]]);export{p as __pageData,_ as default};
